import{_ as o,o as u,c as q,ag as l}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"06 职场·社会·骗局 精读笔记","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/notes/06_职场社会与骗局.md","filePath":"topics/tianya/notes/06_职场社会与骗局.md"}'),i={name:"topics/tianya/notes/06_职场社会与骗局.md"};function a(e,t,r,n,h,s){return u(),q("div",null,[...t[0]||(t[0]=[l('<h1 id="_06-职场·社会·骗局-精读笔记" tabindex="-1">06 职场·社会·骗局 精读笔记 <a class="header-anchor" href="#_06-职场·社会·骗局-精读笔记" aria-label="Permalink to &quot;06 职场·社会·骗局 精读笔记&quot;">​</a></h1><blockquote><p>覆盖12帖：职场（47/53/152）、骗局（156/17/137/134）、猎奇（81）、两性与生意（178/125/160）、物价考古（7）。观点均出自原帖。</p></blockquote><h2 id="_1-《职业如何规划》——鸟树下睡懒觉的猪-2013-11–2018-11" tabindex="-1">1. 《职业如何规划》——鸟树下睡懒觉的猪（2013.11–2018.11） <a class="header-anchor" href="#_1-《职业如何规划》——鸟树下睡懒觉的猪-2013-11–2018-11" aria-label="Permalink to &quot;1. 《职业如何规划》——鸟树下睡懒觉的猪（2013.11–2018.11）&quot;">​</a></h2><p>211土木毕业，工程局→马来西亚工地→设计院→回四线城市老家，兼理财版版主。</p><ul><li>工程局真苦：&quot;一年走掉一半，三年剩四分之一&quot;；可怕的不是流血流汗，是&quot;看不到尽头绵绵不绝的苦&quot;。</li><li>土木排序：能进设计院别去施工；本科能进好设计院就别读研；转行趁早，注册证是硬通货。</li><li>大小城市：先去大城市见世面，&quot;工作两三年后再评估&quot;；年长求安稳可回小城市，&quot;怎么选都有得有失&quot;。</li><li>忌裸辞，&quot;凡事给自己想好退路&quot;（以爱裸辞的老婆为反面教材）；家庭收入不能太单一，最好三种支柱，专业是最后保障。2018年对房市、P2P的悲观判断大多兑现。 框架：<strong>先平台后地域</strong>——年轻用大城市换能力，中年用小城市换生活。 金句：①&quot;别人的错误，你想犯一定可以重蹈覆辙。&quot;②&quot;江湖就是人情世故。&quot;</li></ul><h2 id="_2-《互联网-裁员-大潮将起》——金乐福-转朱思码记-2018-9–12" tabindex="-1">2. 《互联网&quot;裁员&quot;大潮将起》——金乐福（转朱思码记），2018.9–12 <a class="header-anchor" href="#_2-《互联网-裁员-大潮将起》——金乐福-转朱思码记-2018-9–12" aria-label="Permalink to &quot;2. 《互联网&quot;裁员&quot;大潮将起》——金乐福（转朱思码记），2018.9–12&quot;">​</a></h2><ul><li>时间线：2018.6 P2P爆雷→7月社保改税务征收（用工成本升20–30%）→8月起美图、拉勾、碧桂园、魅族&quot;人员优化&quot;。</li><li>数据：百度、阿里工号双双破16万，18年间至少22万人离开；&quot;处理人走人留，不全是因为&#39;钱的没到位&#39;&quot;。</li><li>中年危机：第一代互联网人占着中层，薪资高、体力不如90后，业务承压时最先被优化；冲击顺序是传统行业→P2P→互联网。</li><li>名场面：裁员话术阶梯——&quot;10%叫人员优化……100%降维优化&quot;。</li><li>智联数据：2018Q3互联网招聘职位同比-51%；&quot;不是寒冬将至，而是寒冬已至&quot;。最受伤的是房贷车贷加孩子的中年人与834万应届生。 框架：裁员三动因（合并/战略失误/行业周期）——分清自己是&quot;成本&quot;还是&quot;资产&quot;，钱荒前备好第二技能。 金句：&quot;寒冬的绝望不只是割韭菜时的毫不手软，而是赶尽杀绝时的心狠手辣。&quot;</li></ul><h2 id="_3-《社会不教-精英不讲-坎儿还得自己过》——e路狂飙-刘如江-2012–2016" tabindex="-1">3. 《社会不教，精英不讲，坎儿还得自己过》——e路狂飙（刘如江），2012–2016 <a class="header-anchor" href="#_3-《社会不教-精英不讲-坎儿还得自己过》——e路狂飙-刘如江-2012–2016" aria-label="Permalink to &quot;3. 《社会不教，精英不讲，坎儿还得自己过》——e路狂飙（刘如江），2012–2016&quot;">​</a></h2><p>&quot;九代穷&quot;农家子弟的8年职场悟道，50条铁律，总结世家精英不外传的&quot;理念+习惯+方法&quot;体系。</p><ul><li>精英扎堆的密码不是血统，是可传承的完整体系；信息鸿沟让穷人&quot;吃十堑长一智&quot;。</li><li>改命四机会：出身、升学、就业、婚姻。婚姻是两家资源整合——裴柏村59位宰相靠联姻网络，卫青、诸葛亮皆&quot;攀过高枝&quot;。</li><li>警惕垃圾工作与陷阱工作：打杂积累不到资源；&quot;清洗老员工&quot;的空降岗九死一生；做多了，你在别人眼里也就&quot;垃圾&quot;了。</li><li>敢接&quot;适度超能力&quot;的挑战：连拒三四次，机会就不再找你；远超能力的要躲。</li><li>职场本质是利益：&quot;最重要的是使自己具有较好的利用价值。&quot;</li><li>案例：留美博士15年不跳槽，空降CEO一年出局——太顺的人最容易掉进陷阱岗位。 框架：接活前三问：有无技术含量？是否替人探路？做砸了算谁的？ 金句：①&quot;自救者天救之。&quot;②&quot;永远的稳定是不存在的。&quot;</li></ul><h2 id="_4-《惊天骗局-高级招商主管的自白》——神之手123-2007-11" tabindex="-1">4. 《惊天骗局：高级招商主管的自白》——神之手123，2007.11 <a class="header-anchor" href="#_4-《惊天骗局-高级招商主管的自白》——神之手123-2007-11" aria-label="Permalink to &quot;4. 《惊天骗局：高级招商主管的自白》——神之手123，2007.11&quot;">​</a></h2><p>北漂两年后良心觉醒，揭老东家服装加盟骗局。</p><ul><li>合法注册的皮包公司：法人挂名退休老头，无工厂，&quot;品牌&quot;凭空注册。</li><li>样板店戏法：名牌买来撕标换自家商标；发给加盟商的是批发市场积压货，贴标涨三倍——拿货价高于零售价，&quot;怎么还能不倒闭&quot;。</li><li>话术：话务员八仙过海（套感情/装专业/威胁名额/冒充副总）；看厂称&quot;不对外开放&quot;；只带看打过招呼的两家店。户均收6万，三年近600家，老板净落约两千万。</li><li>觉醒点：残疾农民工老于拿工伤赔偿金加盟，血本无归来讨钱，被&quot;像拖死狗一样拖出去&quot;；作者匿名汇还6万后发帖自曝。</li><li>四条防骗铁律：①项目名+&quot;骗子&quot;搜索，投诉多即骗局；②总部所在城市没有两家以上实体店即是骗子；③一犹豫就送礼减费返现的要警惕；④无论厂址多远，也要亲眼看工厂仓库。 框架：<strong>成本倒推识局</strong>——想清&quot;它承诺的利润从谁身上来&quot;。 金句：&quot;遵照这四条，一万家里可能找不出一家真的。&quot;</li></ul><h2 id="_5-《中国式骗局大全》-出版名《江湖三十年》-——我是骗子他祖宗-2014–2017" tabindex="-1">5. 《中国式骗局大全》（出版名《江湖三十年》）——我是骗子他祖宗，2014–2017 <a class="header-anchor" href="#_5-《中国式骗局大全》-出版名《江湖三十年》-——我是骗子他祖宗-2014–2017" aria-label="Permalink to &quot;5. 《中国式骗局大全》（出版名《江湖三十年》）——我是骗子他祖宗，2014–2017&quot;">​</a></h2><p>96岁老骗子自述体小说，获第二届网络文学双年奖。</p><ul><li>骗术第一原理：&quot;任何一种骗术，都首先需要取得对方的信任。&quot;骗比偷高级——偷有风险，骗是&quot;你乖乖把钱财送上来&quot;。</li><li>门类：江相派（算命看相，讲规矩）、放鹞子（跨省婚骗，专挑偏远老光棍）、做旧业（假古玩+字画作旧+托儿带路）。</li><li>名局：金项圈局（反复逗弄建立熟悉感后消失）；温纯征磨盘破沉尸案——&quot;关键不在足智多谋，在凶手贪那五十两银子&quot;。</li><li>门派伦理：江相派天下一家互相接济；做旧业互相拆台，作者比之为三聚氰胺地沟油。老骗子骗尽众人，到老无儿无女，&quot;一切都是空&quot;。 框架：防骗三问——他为什么对我这么好？好处在谁身上？我是否在拿不该得的便宜？不贪，局就破了一半。 金句：&quot;受骗者不贪，行骗者哪里会有机会？&quot;</li></ul><h2 id="_6-《蜂麻燕雀》——夜半微风之老鬼-2017" tabindex="-1">6. 《蜂麻燕雀》——夜半微风之老鬼，2017 <a class="header-anchor" href="#_6-《蜂麻燕雀》——夜半微风之老鬼-2017" aria-label="Permalink to &quot;6. 《蜂麻燕雀》——夜半微风之老鬼，2017&quot;">​</a></h2><p>民国江湖小说，借老骗子之口讲骗子四大门。</p><ul><li>四大门：蜂（团伙设局，托儿、撬边、掌眼分工如蜂群）、麻/马（装神弄鬼请大仙）、燕（美色局）、缺（不择手段伤人性命）。</li><li>门规：蜂麻燕三门严禁伤人，&quot;要给自己留阴德&quot;；坏规矩者由家主发追讨令，全门共诛。</li><li>组织学：马家门马头—掌灯使—八骏马，内斗与借刀杀人写尽江湖权力结构。 框架：识局认角色——一单&quot;好得不像话&quot;的买卖里，谁在当托儿、谁在掌眼、谁等着收网。 金句：①&quot;骗子和骗子是不一样的：有人守规矩讲道义，有人无所不用其极。&quot;②&quot;窃钩者诛，窃国者侯，放到骗上也是一个道理。&quot;</li></ul><h2 id="_7-《818天涯中有炒作嫌疑的热帖》——小光头我小光头我-2010" tabindex="-1">7. 《818天涯中有炒作嫌疑的热帖》——小光头我小光头我，2010 <a class="header-anchor" href="#_7-《818天涯中有炒作嫌疑的热帖》——小光头我小光头我-2010" aria-label="Permalink to &quot;7. 《818天涯中有炒作嫌疑的热帖》——小光头我小光头我，2010&quot;">​</a></h2><p>早期网络舆情案例库。</p><ul><li>周公子大战易烨卿（2005）：不谈道德只比富贵，&quot;贵族9问&quot;（表编号、私人律师、慈善、赛马、家庭教师）令自称&quot;上流社会&quot;的易姐哑火；&quot;真正的淑女低调，从不鄙视穷人&quot;。</li><li>陈易卖身救母（2005）：募得近10万后被曝穿名牌，对骂中自认部分细节——捐助悲剧帖的反转模板。</li><li>山西煤老板招女婿（2008）：有车有房有照片的钓鱼帖，收割求婚者个人信息。</li><li>姜岩事件（2007）：丈夫出轨致其写&quot;死亡日记&quot;后自杀，帖内完整呈现&quot;求助—声讨—人肉—隐私灾难&quot;链。 框架：炒作五征兆——剧情过于完整、关键处必有照片自证、当事人只在线上现身、事成后ID消失、存在模糊的受益方。 金句：&quot;想忽悠目光如炬的TYers，还真有难度。&quot;</li></ul><h2 id="_8-《内参记者》——有骨难画-2018-6–12" tabindex="-1">8. 《内参记者》——有骨难画，2018.6–12 <a class="header-anchor" href="#_8-《内参记者》——有骨难画-2018-6–12" aria-label="Permalink to &quot;8. 《内参记者》——有骨难画，2018.6–12&quot;">​</a></h2><p>自称写内部刊物的记者，声明&quot;信不信由你，只负责写不负责解释&quot;。</p><ul><li>《越战诡事》：老山&quot;7.12大战&quot;战史真实可查，随后接入越军&quot;活体生物兵器&quot;（机枪打不死的怪人）——真史料包幻叙事。</li><li>《喋血神农架》：借刘民壮《中国神农架》铺垫野人、驴头狼，称野人尸体标本&quot;超过两位数&quot;，再写随科考队亲历；罗布泊篇有地下巨虫与&quot;沙民&quot;。 框架：识别&quot;权威包装型内容&quot;三件套——真实框架（战役/书名/制度）+不可验证核心+拒绝解释的免责声明；看故事可以，引为事实需独立信源。 金句：&quot;你所看到的，未必就是事情的全部。&quot;&quot;它可能看着有点像小说，但它不是。&quot;（读者恰应反过来读。）</li></ul><h2 id="_9-《记生意场上接触过的有能力的女人们》——赚钱7788-2012–2018" tabindex="-1">9. 《记生意场上接触过的有能力的女人们》——赚钱7788，2012–2018 <a class="header-anchor" href="#_9-《记生意场上接触过的有能力的女人们》——赚钱7788-2012–2018" aria-label="Permalink to &quot;9. 《记生意场上接触过的有能力的女人们》——赚钱7788，2012–2018&quot;">​</a></h2><p>70后，从城管、报社临时工南下做生意，自省&quot;爱赚快钱、眼高手低&quot;。</p><ul><li>底层资源运作：借&quot;上面有人&quot;的模糊话术让基层&quot;遇庙烧香&quot;；自嘲&quot;中国的事情就是官场里的事情&quot;。</li><li>面子观：&quot;爱面子是挣不了钱的，面子是自己本事挣来的。&quot;</li><li>最动人一段：生意赔光只剩100元，妻子&quot;你说吃吧，我喝点汤就行&quot;——&quot;娶一个能和自己吃苦的女人&quot;。</li><li>生意观：&quot;赚钱一定要赚富人的钱，买房开店要离富人近&quot;——受众决定价格弹性。</li><li>中年转折：不再酒桌吆喝接单，&quot;我想做一个有点尊严和诚实信用的人&quot;；又悔&quot;娶了皮革厂老板的妹妹可少奋斗20年——门第观念害死人&quot;。 框架：贴近富人圈子学思维，把信用攒成复利。 金句：&quot;人在理智不清时，能做出不理智的事，吃亏是福。&quot;</li></ul><h2 id="_10-《女性秘史》——fy风月宝鉴-2017-8–2018-2" tabindex="-1">10. 《女性秘史》——FY风月宝鉴，2017.8–2018.2 <a class="header-anchor" href="#_10-《女性秘史》——fy风月宝鉴-2017-8–2018-2" aria-label="Permalink to &quot;10. 《女性秘史》——FY风月宝鉴，2017.8–2018.2&quot;">​</a></h2><p>以史料为底、小说笔法写&quot;女性通史&quot;。</p><ul><li>女娲档案（恶搞简历体）：女神也是单身母亲、部落首领、兼职红娘——母神先于男神，投射早期母系记忆。</li><li>潘金莲翻案线：张大户为长期占有她，定下&quot;长相越丑越好、家越穷越老、人越窝囊越好、住得越近越好&quot;的择偶标准塞给武大郎——恶更在制度性安排；武大郎&quot;诚信经营从没害过人&quot;，其实比潘金莲更不幸。</li><li>&quot;女人三性&quot;：母性（不生不灭的本能）→女性（两性分化后的本能）→社会性（超越本能的高层存在），三位一体。 框架：看女人先看处境——放回其权力与经济结构，再谈道德判决。 金句：①&quot;做女人难，做名女人更难，做女神难上加难。&quot;②&quot;人类的鄙视链，从女娲甩泥点那天就形成了。&quot;</li></ul><h2 id="_11-《狐狸精修炼秘笈》——luomeihengdi-落梅-2011-11–2016-3" tabindex="-1">11. 《狐狸精修炼秘笈》——luomeihengdi（落梅），2011.11–2016.3 <a class="header-anchor" href="#_11-《狐狸精修炼秘笈》——luomeihengdi-落梅-2011-11–2016-3" aria-label="Permalink to &quot;11. 《狐狸精修炼秘笈》——luomeihengdi（落梅），2011.11–2016.3&quot;">​</a></h2><p>中年职场女性的情感咨询帖合集。</p><ul><li>立论：&quot;能成为狐狸精的只有一种女人——了解男人的女人&quot;，与容貌智商无关。</li><li>男人画像：视觉动物；热恋期荷尔蒙只能维持两三年，理性回归后不再迁就——&quot;婚前婚后两幅面孔&quot;是阶段使然；女人若仍在心理优势里任性，必遭&quot;迎头痛击&quot;。</li><li>变美实操：没有丑女人只有懒女人；保湿是大头；黄瓜片敷脸&quot;贵在坚持&quot;；反对整形（列割双眼皮、削骨、隆胸之后遗症）。</li><li>关系法则：性格对女人幸福的关联度&quot;达到80%&quot;；情场最失意的不是容貌差的，是脾气差的；聪明的狐狸精绝不当小三；&quot;让彼此更契合、让他更爱你，比所有监管手段都管用&quot;。</li><li>危机处理：要离就立刻请律师收集证据，&quot;第一次起诉通常不判离，过半年继续起诉&quot;。 框架：先自省后归因——分清&quot;阶段差&quot;与&quot;人品差&quot;，前者调预期，后者止损。 金句：①&quot;出来混，总是要还的。&quot;②&quot;发火跟崩溃没有任何意义。&quot;</li></ul><h2 id="_12-《一百元人民币在泰国能做什么》——骑白马的农民-2011-8-物价考古" tabindex="-1">12. 《一百元人民币在泰国能做什么》——骑白马的农民，2011.8（物价考古） <a class="header-anchor" href="#_12-《一百元人民币在泰国能做什么》——骑白马的农民-2011-8-物价考古" aria-label="Permalink to &quot;12. 《一百元人民币在泰国能做什么》——骑白马的农民，2011.8（物价考古）&quot;">​</a></h2><p>背包客五年五次赴泰，汇率4.7:1（100元≈470铢）。2011年8月实拍价，2010年代初物价一手标本：</p><ul><li>吃：快餐30–35铢全国统一（6.4–7.4元），曼谷机场同价；排骨135铢/公斤（100元买3.5kg）；整鸡94铢/公斤；秋刀鱼14铢/条；产地山竹10铢/公斤；牛奶5L装177铢；超市米4元+/斤。</li><li>用：欧莱雅约为国内1/3–1/4；Swensen&#39;s双人冰激凌148铢。</li><li>行：汽油约8.5元/升但全境高速免费；曼谷有免费公交；曼谷—清迈700km双层VIP大巴300–350铢；对照&quot;国内300公里车票140元&quot;。</li><li>住：曼谷180km外900平独立屋约85万元；海滨31平全装修公寓11万元。</li><li>收入福利：最低月薪6500铢（约1350元）；公司职员1.2–1.5万铢；教授10万铢；用电90度以下免费、学生免费牛奶、&quot;30铢看病&quot;。</li><li>横向感受：曼谷快餐三年几乎没涨，而作者离国一月间国内排骨从22元涨到30元/斤——&quot;短短三年，恍若隔世&quot;。后半段骂战亦是当年论坛生态标本。 框架：比价看结构——&quot;工资/物价/福利/物价稳定性&quot;四件套才是真实生活成本。 金句：①&quot;天堂是比来的。&quot;②&quot;如果一个国家不能给子民以安全感，子民唯有如沉船前的老鼠，纷纷逃窜自保。&quot;</li></ul><h2 id="_13-总览与心得" tabindex="-1">13. 总览与心得 <a class="header-anchor" href="#_13-总览与心得" aria-label="Permalink to &quot;13. 总览与心得&quot;">​</a></h2><p><strong>骗局恒久远，套路永流传。</strong> 加盟骗局、江湖骗局、民国骗术小说，内核一致：先取信，后收网；你的贪念就是他的杠杆。神之手的四条铁律、&quot;不贪破局&quot;、&quot;认角色&quot;，合成一套防骗系统——考察实物、搜差评、算清利益流向、看谁在陪你演戏。放到今天的&quot;理财课堂&quot;&quot;杀猪盘&quot;，一条不用改。</p><p><strong>职场底层是利益与位置，不是苦劳。</strong> e路狂飙：决定报酬的是&quot;利用价值&quot;，决定前程的是不替人做陷阱工作、不拒适度挑战；鸟树用15年验证：平台&gt;地域&gt;努力，第二技能&gt;加班。裁员帖是残酷反面——当你只是&quot;成本&quot;，寒冬第一刀就落在你头上。年轻时把自己练成资产，中年不押注单一平台。</p><p><strong>婚姻与资源捆绑，两性叙事在演进。</strong> e路狂飙主张&quot;攀龙附凤&quot;，赚钱7788自省&quot;门第观念害死人&quot;，落梅说&quot;性格关联80%的幸福&quot;，风月宝鉴借潘金莲提醒：许多&quot;水性杨花&quot;的判决，忽略了她只是被制度摆布。从&quot;婚姻是资源整合&quot;到&quot;先看人性与处境&quot;，四帖画出一条演化的线。</p><p><strong>信息识别是基本功。</strong> 134帖的炒作案例库与人肉灾难、81帖的&quot;内参体&quot;猎奇，是同一枚硬币的两面。检测器只有两个：利益归谁，证据可否独立验证。2010年适用，今天更适用。</p><p><strong>国别比较的价值在方法不在结论。</strong> 泰国帖用&quot;工资—物价—福利—稳定性&quot;四维对比取代情绪吹贬，并自认&quot;不懂泰语难免谬误&quot;；评论区骂战则示范立场如何污染事实。&quot;有图有真相+承认局限&quot;，是信息洪流里最稀缺的姿态。</p><p><strong>江湖的最终账本上是良心。</strong> 老骗子孤独终老，好骗子守&quot;留阴德&quot;的门规，加盟主管匿名还钱，生意人中年只求&quot;做个有点尊严和诚实信用的人&quot;。天涯式江湖里，规矩、信用、阴德，比机灵值钱——这是这批帖子跨越十几年仍可读的原因。</p>',44)])])}const p=o(i,[["render",a]]);export{d as __pageData,p as default};
